        ) AS t(code, nom, type_voie, variantes, geojson)
    LOOP
        INSERT INTO app.rue (commune_id, code, nom, type_voie, source, variantes,
                             a_remplacer, geom, longueur_m)
        VALUES (v_commune, v_r.code, v_r.nom, v_r.type_voie, 'osm',
                v_r.variantes, true,
                ST_Multi(ST_SetSRID(ST_GeomFromGeoJSON(v_r.geojson), 4326)),
                round(ST_Length(ST_SetSRID(ST_GeomFromGeoJSON(v_r.geojson), 4326)::geography)::numeric, 1))
        ON CONFLICT (commune_id, code) DO UPDATE SET
            geom        = coalesce(app.rue.geom, EXCLUDED.geom),
            longueur_m  = coalesce(app.rue.longueur_m, EXCLUDED.longueur_m),
            variantes   = ARRAY(SELECT DISTINCT unnest(app.rue.variantes || EXCLUDED.variantes)),
            a_remplacer = app.rue.a_remplacer,
            modifie_le  = now();
        v_n := v_n + 1;
    END LOOP;

    RAISE NOTICE '[seed 0013] % voies OpenStreetMap posées (à valider par la mairie)', v_n;
